query-logpresso.query:
table duration=1m ts_data_view_m14a | search MESSAGENAME == "RAIL-CARRIERTRANSFERREPLY" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID ,CARRIER | sort _time | fields _time,MESSAGENAME,COMMANDID,CARRIER,MACHINENAME | eval _time = string(_time, "yyyyMMddHHmmssSSS") | rename _time as ETIME, MESSAGENAME as EMESSAGENAME | sort ETIME | join COMMANDID [ table duration=10m ts_data_view_m14a | search MESSAGENAME == "RAIL-CARRIERTRANSFER" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID ,CARRIER | sort _time | stats last(_time) as _time by MACHINENAME,MESSAGENAME, SECSII,COMMANDID,TRANSACTIONID | fields _time,MESSAGENAME,COMMANDID,CARRIER,MACHINENAME | eval _time = string(_time, "yyyyMMddHHmmssSSS") | rename _time as STIME, MESSAGENAME as SMESSAGENAME | sort STIME ] | search date(ETIME,"yyyyMMddHHmmssSSS") > date(STIME,"yyyyMMddHHmmssSSS") | eval MESSAGE_TIME = datediff(date(STIME,"yyyyMMddHHmmssSSS"),date(ETIME,"yyyyMMddHHmmssSSS"),"msec")/1000 ,TIME = string(now(),"yyyyMMddHHmm") | fields TIME,COMMANDID,MACHINENAME,MESSAGE_TIME | eval MESSAGE_TYP = "REP" | stats avg(MESSAGE_TIME) as MESSAGE_TIME by TIME,MACHINENAME, MESSAGE_TYP | eval MESSAGE_TIME = round(MESSAGE_TIME,2) , RN="1" | union [ table duration=1m ts_data_view_m14a | search MESSAGENAME == "RAIL-VEHICLEASSIGNED" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID ,CARRIER | sort _time | fields _time,MESSAGENAME,COMMANDID,CARRIER,MACHINENAME | eval _time = string(_time, "yyyyMMddHHmmssSSS") | rename _time as ETIME, MESSAGENAME as EMESSAGENAME | sort ETIME | join COMMANDID [ table duration=10m ts_data_view_m14a | search MESSAGENAME == "RAIL-CARRIERTRANSFERREPLY" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID ,CARRIER | sort _time | fields _time,MESSAGENAME,COMMANDID,CARRIER,MACHINENAME | eval _time = string(_time, "yyyyMMddHHmmssSSS") | stats last(_time) as _time by MESSAGENAME,COMMANDID,MACHINENAME | rename _time as STIME, MESSAGENAME as SMESSAGENAME | sort STIME ] | search date(ETIME,"yyyyMMddHHmmssSSS") > date(STIME,"yyyyMMddHHmmssSSS") | eval MESSAGE_TIME = datediff(date(STIME,"yyyyMMddHHmmssSSS"),date(ETIME,"yyyyMMddHHmmssSSS"),"msec")/1000 ,TIME = string(now(),"yyyyMMddHHmm") | fields TIME,COMMANDID,MACHINENAME,MESSAGE_TIME | eval MESSAGE_TYP = "ASSIGN" | stats avg(MESSAGE_TIME) as MESSAGE_TIME by TIME,MACHINENAME, MESSAGE_TYP | eval MESSAGE_TIME = round(MESSAGE_TIME,2) , RN="2" ] | union [ table duration=1m ts_data_view_m14a | search MESSAGENAME == "RAIL-CARRIERINSTALLED" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID ,CARRIER | sort _time | fields _time,MESSAGENAME,COMMANDID,CARRIER,MACHINENAME | eval _time = string(_time, "yyyyMMddHHmmssSSS") | rename _time as ETIME, MESSAGENAME as EMESSAGENAME | sort ETIME | join COMMANDID [ table duration=10m ts_data_view_m14a | search MESSAGENAME == "RAIL-VEHICLEASSIGNED" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID | sort _time | fields _time,MESSAGENAME,COMMANDID,CARRIER,MACHINENAME | eval _time = string(_time, "yyyyMMddHHmmssSSS") | stats last(_time) as _time by MESSAGENAME,COMMANDID,MACHINENAME | rename _time as STIME, MESSAGENAME as SMESSAGENAME | sort STIME ] | search date(ETIME,"yyyyMMddHHmmssSSS") > date(STIME,"yyyyMMddHHmmssSSS") | eval MESSAGE_TIME = datediff(date(STIME,"yyyyMMddHHmmssSSS"),date(ETIME,"yyyyMMddHHmmssSSS"),"msec")/1000 ,TIME = string(now(),"yyyyMMddHHmm") | fields TIME,COMMANDID,MACHINENAME,MESSAGE_TIME | eval MESSAGE_TYP = "ACQUIRED" | stats avg(MESSAGE_TIME) as MESSAGE_TIME by TIME,MACHINENAME, MESSAGE_TYP | eval MESSAGE_TIME = round(MESSAGE_TIME,2) , RN="3" ] | union [ table duration=1m ts_data_view_m14a | search MESSAGENAME == "RAIL-CARRIERREMOVED" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID ,CARRIER | sort _time | fields _time,MESSAGENAME,COMMANDID,CARRIER,MACHINENAME | eval _time = string(_time, "yyyyMMddHHmmssSSS") | rename _time as ETIME, MESSAGENAME as EMESSAGENAME | sort ETIME | join COMMANDID [ table duration=10m ts_data_view_m14a | search MESSAGENAME == "RAIL-CARRIERINSTALLED" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID ,CARRIER | sort _time | fields _time,MESSAGENAME,COMMANDID,CARRIER,MACHINENAME | eval _time = string(_time, "yyyyMMddHHmmssSSS") | stats last(_time) as _time by MESSAGENAME,COMMANDID,MACHINENAME | rename _time as STIME, MESSAGENAME as SMESSAGENAME | sort STIME ] | search date(ETIME,"yyyyMMddHHmmssSSS") > date(STIME,"yyyyMMddHHmmssSSS") | eval MESSAGE_TIME = datediff(date(STIME,"yyyyMMddHHmmssSSS"),date(ETIME,"yyyyMMddHHmmssSSS"),"msec")/1000 ,TIME = string(now(),"yyyyMMddHHmm") | fields TIME,COMMANDID,MACHINENAME,MESSAGE_TIME | eval MESSAGE_TYP = "TRANSFERRING" | stats avg(MESSAGE_TIME) as MESSAGE_TIME by TIME,MACHINENAME, MESSAGE_TYP | eval MESSAGE_TIME = round(MESSAGE_TIME,2) , RN="4" ] | union [ table duration=1m ts_data_view_m14a | search MESSAGENAME == "RAIL-VEHICLEDEPOSITCOMPLETED" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID ,CARRIER | sort _time | fields _time,MESSAGENAME,COMMANDID,CARRIER,MACHINENAME | eval _time = string(_time, "yyyyMMddHHmmssSSS") | rename _time as ETIME, MESSAGENAME as EMESSAGENAME | sort ETIME | join CARRIER [ table duration=10m ts_data_view_m14a | search MESSAGENAME == "RAIL-VEHICLEDEPOSITSTARTED" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID ,CARRIER | sort _time | fields _time,MESSAGENAME,COMMANDID,CARRIER,MACHINENAME | eval _time = string(_time, "yyyyMMddHHmmssSSS") | stats last(_time) as _time by MESSAGENAME,CARRIER,MACHINENAME | rename _time as STIME, MESSAGENAME as SMESSAGENAME | sort STIME ] | search date(ETIME,"yyyyMMddHHmmssSSS") > date(STIME,"yyyyMMddHHmmssSSS") | eval MESSAGE_TIME = datediff(date(STIME,"yyyyMMddHHmmssSSS"),date(ETIME,"yyyyMMddHHmmssSSS"),"msec")/1000 ,TIME = string(now(),"yyyyMMddHHmm") | fields TIME,COMMANDID,MACHINENAME,MESSAGE_TIME | eval MESSAGE_TYP = "DESPOSITED" | stats avg(MESSAGE_TIME) as MESSAGE_TIME by TIME,MACHINENAME, MESSAGE_TYP | eval MESSAGE_TIME = round(MESSAGE_TIME,2) , RN="5" ] | union [
table duration=1m ts_data_view_m14a | search MESSAGENAME == "RAIL-TRANSFERCOMPLETED" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID ,SECSII | rex field=SECSII "<A,14 \[CARRIERLOC\] '(?<CARRIERLOC>[^']+)'>" | sort _time | fields _time,MESSAGENAME,COMMANDID,MACHINENAME,CARRIERLOC | eval _time = string(_time, "yyyyMMddHHmmssSSS") | rename _time as ETIME, MESSAGENAME as SMESSAGENAME | sort ETIME | join COMMANDID,CARRIERLOC [ table duration=10m ts_data_view_m14a | search MESSAGENAME == "RAIL-CARRIERREMOVED" | fields _time,MACHINENAME,MESSAGENAME ,COMMANDID ,SECSII | rex field=SECSII "<A,14 \[CARRIERLOC\] '(?<CARRIERLOC>[^']+)'>" | sort _time | fields _time,MESSAGENAME,COMMANDID,MACHINENAME,CARRIERLOC | eval _time = string(_time, "yyyyMMddHHmmssSSS") | rename _time as STIME, MESSAGENAME as EMESSAGENAME | sort STIME ] | eval MESSAGE_TIME = datediff(date(STIME,"yyyyMMddHHmmssSSS"),date(ETIME,"yyyyMMddHHmmssSSS"),"msec")/1000 ,TIME = string(now(),"yyyyMMddHHmm") | fields TIME,COMMANDID,MACHINENAME,MESSAGE_TIME | eval MESSAGE_TYP = "COMPLETED" | stats avg(MESSAGE_TIME) as MESSAGE_TIME by TIME,MACHINENAME, MESSAGE_TYP | eval MESSAGE_TIME = round(MESSAGE_TIME,2) , RN="6"
] | sort RN | eval TIME = string(date(TIME,"yyyyMMddHHmm"),"yyyy-MM-dd HH:mm"),ALARM = "N", MESSAGE_TIME = case(MESSAGE_TIME < 0 , 0 ,MESSAGE_TIME) | fields TIME, MACHINENAME, MESSAGE_TYP, MESSAGE_TIME,ALARM | eval IDC_NM = "MIN" | fields TIME, MACHINENAME, MESSAGE_TYP, MESSAGE_TIME, ALARM, IDC_NM

